//! The physics program task (plan C3): candidates are MAGE integrators, ranked
//! by held-out rollout error, and a contract refuses the ones that do not
//! conserve energy.
//!
//! A candidate is a `.mg` file under `examples/physics_task/` that defines one
//! function, `@role(candidate) f step(s: [f64], k: f64, dt: f64) -> [f64]`, for
//! an undamped unit-mass spring. `task.mg.in` holds everything else: the energy,
//! the `@ens` on `advance` that every step passes through, the rollout, the
//! held-out reference trajectories (the exact solution, generated by
//! `scripts/physics-task-reference.py`) and `score`, the RMS position error.
//!
//! The harness is this file. It admits a candidate only if it is that one
//! function and passes `--check --core` (so its role caps it at pure), appends
//! it to the task, checks the composition, and runs `score` with
//! `mage-parse --eval … --fuel`, the fuel-bounded evaluator the arena uses.
//! A candidate either gets a score or is refused with the contract named.
//!
//! The population is fixed: two correct integrators, two wrong ones and one
//! that conserves energy by never moving. What is asserted is what is true of
//! them: Verlet beats symplectic Euler, both beat the frozen state, and the two
//! energy-gaining integrators are refused.

use std::path::{Path, PathBuf};
use std::process::Command;

/// The fuel for one scoring run. A full run of either correct integrator spends
/// about 18,000-23,000, so this only bounds a candidate that loops.
const FUEL: &str = "1000000";

/// The clause a refused candidate must be refused by, as the violation quotes it.
const CONTRACT: &str = "`@ens(abs(energy(result, k) - e0) <= DRIFT * e0, \
                        \"energy stays within DRIFT of its initial value\")` of `advance` (sp advance)";

fn bin() -> PathBuf {
    // `target/<profile>/deps/<test>` — the binary is two levels up.
    let mut p = std::env::current_exe().expect("test binary path");
    p.pop();
    p.pop();
    p.push(if cfg!(windows) { "mage-parse.exe" } else { "mage-parse" });
    assert!(p.exists(), "mage-parse not built at {p:?}");
    p
}

fn task_dir() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR")).join("examples").join("physics_task")
}

fn read(path: &Path) -> String {
    std::fs::read_to_string(path).unwrap_or_else(|e| panic!("read {path:?}: {e}"))
}

fn run(args: &[&str], file: &Path) -> (String, String, i32) {
    let out = Command::new(bin()).args(args).arg(file).output().expect("spawn mage-parse");
    (
        String::from_utf8_lossy(&out.stdout).into_owned(),
        String::from_utf8_lossy(&out.stderr).into_owned(),
        out.status.code().unwrap_or(-1),
    )
}

/// What the harness says about one candidate.
#[derive(Debug)]
enum Verdict {
    /// The RMS position error over the held-out cases; lower is better.
    Scored(f64),
    /// The run failed; the evaluator's message.
    Refused(String),
}

/// Admit `candidate` (a file name under `examples/physics_task/`), compose it
/// with `task`, and score it.
fn judge(task: &str, candidate: &str) -> Verdict {
    let path = task_dir().join(candidate);
    let src = read(&path);

    // Admission: exactly one item, `step`, roled `candidate`. A candidate that
    // brought its own `advance` or `sp` could replace the task's contract.
    let module = mage_prototype::parser::parse(&mage_prototype::lexer::lex(&src))
        .unwrap_or_else(|e| panic!("{candidate}: parse error {}:{}: {}", e.line, e.col, e.message));
    assert_eq!(module.items.len(), 1, "{candidate}: a candidate is one function");
    let item = &module.items[0];
    match &item.kind {
        mage_prototype::ast::ItemKind::Function(fd) => assert_eq!(fd.name, "step", "{candidate}"),
        _ => panic!("{candidate}: a candidate is one function"),
    }
    assert!(
        item.attributes.iter().any(|a| a.name == "role" && a.args == ["candidate"]),
        "{candidate}: `step` must be @role(candidate)"
    );
    let (_, stderr, code) = run(&["--check", "--core"], &path);
    assert!(code == 0 && stderr.contains("Errors: 0"), "{candidate}: --check --core:\n{stderr}");

    // Compose, check the composition, and score it under fuel.
    // One directory per call: the tests run in parallel, and the break-check
    // writes a different program for the same candidate.
    static CALLS: std::sync::atomic::AtomicUsize = std::sync::atomic::AtomicUsize::new(0);
    let n = CALLS.fetch_add(1, std::sync::atomic::Ordering::Relaxed);
    let dir = std::env::temp_dir().join(format!("mage-physics-{}-{n}-{candidate}", std::process::id()));
    let _ = std::fs::remove_dir_all(&dir);
    std::fs::create_dir_all(&dir).expect("temp dir");
    let program = dir.join("program.mg");
    std::fs::write(&program, format!("{task}\n{src}")).expect("write program");
    let (_, stderr, code) = run(&["--check"], &program);
    assert!(code == 0 && stderr.contains("Errors: 0"), "{candidate}: composed --check:\n{stderr}");
    let (stdout, stderr, code) = Command::new(bin())
        .args(["--eval"])
        .arg(&program)
        .args(["score", "--fuel", FUEL])
        .output()
        .map(|o| {
            (
                String::from_utf8_lossy(&o.stdout).into_owned(),
                String::from_utf8_lossy(&o.stderr).into_owned(),
                o.status.code().unwrap_or(-1),
            )
        })
        .expect("spawn mage-parse");
    let _ = std::fs::remove_dir_all(&dir);
    assert!(stderr.contains("fuel spent: "), "{candidate}: not run under fuel:\n{stderr}");
    if code == 0 {
        let score: f64 = stdout.trim().parse().unwrap_or_else(|e| panic!("{candidate}: {e}: {stdout:?}"));
        Verdict::Scored(score)
    } else {
        Verdict::Refused(stderr)
    }
}

fn task() -> String {
    // Line endings normalised, so the break-check finds the block on a
    // checkout that converts them.
    read(&task_dir().join("task.mg.in")).replace("\r\n", "\n")
}

fn scored(task: &str, candidate: &str) -> f64 {
    match judge(task, candidate) {
        Verdict::Scored(s) => s,
        Verdict::Refused(e) => panic!("{candidate} was refused:\n{e}"),
    }
}

fn refused(task: &str, candidate: &str) -> String {
    match judge(task, candidate) {
        Verdict::Refused(e) => e,
        Verdict::Scored(s) => panic!("{candidate} was accepted with score {s}"),
    }
}

#[test]
fn the_population_is_ranked_and_the_wrong_integrators_are_refused() {
    let task = task();
    let verlet = scored(&task, "velocity_verlet.mg");
    let euler = scored(&task, "symplectic_euler.mg");
    let frozen = scored(&task, "frozen.mg");

    // Second order beats first order by more than an order of magnitude at
    // w dt <= 0.1, and the frozen state, which conserves energy exactly, is
    // last: the contract is necessary, not sufficient.
    assert!(verlet < 0.002, "Verlet RMS error {verlet}");
    assert!(euler < 0.03, "symplectic Euler RMS error {euler}");
    assert!(verlet * 10.0 < euler, "Verlet {verlet} vs symplectic Euler {euler}");
    assert!(frozen > 0.5, "frozen RMS error {frozen}");

    for wrong in ["explicit_euler.mg", "verlet_missing_half.mg"] {
        let e = refused(&task, wrong);
        assert!(e.contains(&format!("contract violated: {CONTRACT} is false")), "{wrong}:\n{e}");
    }
}

#[test]
fn explicit_euler_is_refused_at_the_step_that_crosses_the_bound() {
    // Energy grows by exactly 1 + k dt^2 = 1.01 per step at k = 4, dt = 0.05,
    // so step 10 is the first beyond 10% (1.01^10 = 1.1046), at x = 0.57079...
    let e = refused(&task(), "explicit_euler.mg");
    assert!(
        e.contains(&format!(
            "contract violated: {CONTRACT} is false: `advance` returned [0.5707904498999999, -1.7650160200000002]"
        )),
        "got:\n{e}"
    );
}

#[test]
fn without_the_contract_explicit_euler_is_accepted() {
    // Break-check: the refusal is the contract's doing. Drop the `sp advance`
    // block and the same candidate runs to the end and gets a score, a bad one.
    let task = task();
    let start = task.find("sp advance {").expect("the task has the contract");
    let end = start + task[start..].find("\n}\n").expect("the contract block ends") + 3;
    let unguarded = format!("{}{}", &task[..start], &task[end..]);
    assert!(!unguarded.contains("@ens"), "the contract is gone");
    let score = scored(&unguarded, "explicit_euler.mg");
    let verlet = scored(&unguarded, "velocity_verlet.mg");
    assert!(score > 100.0 * verlet, "explicit Euler {score} vs Verlet {verlet}");
}
